import sales from './sales.json' with {type:'json'};

const ISO_DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

function isValidISODate(s) {
  if (typeof s !== 'string' || !ISO_DATE_RE.test(s)) return false;
  const { 0: y, 1: m, 2: d } = s.split('-').map(Number);
  const dt = new Date(Date.UTC(y, m - 1, d));
  return (
    dt.getUTCFullYear() === y &&
    dt.getUTCMonth() === m - 1 &&
    dt.getUTCDate() === d
  );
}

export async function listTools() {
  return [
    {
      name: 'sales_report',
      description:
        'Sum sales rows within an inclusive date range. Returns total amount and row count.',
      inputSchema: {
        type: 'object',
        properties: {
          start_date: { type: 'string', description: 'Inclusive start date in ISO format YYYY-MM-DD.' },
          end_date: { type: 'string', description: 'Inclusive end date in ISO format YYYY-MM-DD.' },
        },
        required: ['start_date', 'end_date'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'sales_report') {
    throw new Error(`Unknown tool: ${name}`);
  }

  const allowed = ['start_date', 'end_date'];
  for (const key of Object.keys(args)) {
    if (!allowed.includes(key)) {
      throw new Error(`Unexpected field: ${key}`);
    }
  }

  const { start_date, end_date } = args;

  if (!isValidISODate(start_date)) {
    throw new Error('start_date must be a valid ISO date string (YYYY-MM-DD)');
  }
  if (!isValidISODate(end_date)) {
    throw new Error('end_date must be a valid ISO date string (YYYY-MM-DD)');
  }
  if (start_date > end_date) {
    throw new Error('start_date must not be after end_date');
  }

  let total = 0;
  let count = 0;
  for (const row of sales) {
    if (row.date >= start_date && row.date <= end_date) {
      total += row.amount;
      count += 1;
    }
  }

  return {
    content: [
      {
        type: 'text',
        text: `Total amount: ${total}. Row count: ${count}.`,
      },
    ],
  };
}

